#!/usr/bin/env python3
"""Compile actual range matcher and extracted guarded emitter against IR/context fixtures.
These contract tests are not a full emulator build or SPIR-V validator.
"""
from pathlib import Path
import shutil, subprocess, sys
STUB='#pragma once\n#include <cstdint>\n#include <span>\n#include <vector>\n#include <type_traits>\nusing u32=std::uint32_t;using u64=std::uint64_t;using s32=std::int32_t;\nnamespace Shader::Gcn {struct Block;}\nnamespace Shader::IR {\nenum class Type { Void,U32,U1,Opaque,ScalarReg };\nenum class Opcode { Phi,IAdd32,ISub32,IMul32,ShiftLeftLogical32,ShiftRightLogical32,BitwiseAnd32,ConditionRef,SLessThan32,ULessThan32,ImageRead,ImageHandle,CompositeConstructU32x4,CompositeConstructU32x2,ReadConst,ReadConstBuffer,GetUserData,ReadLane,ImageWrite,ImageSampleRaw };\nstruct Inst;struct Block;\nstruct Value {\n IR::Type kind=IR::Type::Void;u32 imm=0;Inst* inst=nullptr;\n Value()=default;explicit Value(u32 n):kind(Type::U32),imm(n){} explicit Value(Inst* p):kind(Type::Opaque),inst(p){}\n bool IsImmediate()const{return kind==Type::U32||kind==Type::U1||kind==Type::ScalarReg;}\n IR::Type Type()const{return kind;}u32 U32()const{return imm;}Inst* TryInst()const{return inst;}\n bool operator==(const Value&)const=default;\n};\nstruct TextureInstInfo {bool is_depth=false,is_array=false,is_r128=false,has_lod=false,has_derivatives=false,is_gather=false;};\nstruct Block {std::vector<Block*> preds;const Shader::Gcn::Block* cfg_block=nullptr;Value branch_cond{};std::span<Block*const> ImmPredecessors()const{return preds;}};\nstruct Inst {\n Opcode opcode;std::vector<Value> args;Block* parent{};std::vector<Block*> phi_blocks;IR::Type type=IR::Type::U32;TextureInstInfo info{};\n explicit Inst(Opcode op):opcode(op){} Opcode GetOpcode()const{return opcode;}std::size_t NumArgs()const{return args.size();}Value Arg(std::size_t i)const{return args.at(i);}Block* GetParent()const{return parent;}Block* PhiBlock(std::size_t i)const{return phi_blocks.at(i);}\n template<class T>T Flags()const{if constexpr(std::is_same_v<T,IR::Type>)return type;else return info;}\n};\n}\nnamespace Shader::Gcn {struct Block {Block* branch_true=nullptr;Block* branch_false=nullptr;IR::Block* ir_block=nullptr;};}\n'
TEST='// Test the actual production matcher with a small IR-interface fixture.\n// Does not compile/link the full emulator or execute Vulkan.\n#include <cstdio>\n#include <memory>\n#include <stdexcept>\n#include "shader_recompiler/ir/passes/finite_raw_image_plan.h"\nusing namespace Shader;using namespace Shader::Optimization::FiniteRawImage;\nusing O=IR::Opcode;using V=IR::Value;\nunsigned checks=0;\n#define CHECK(x) do{++checks;if(!(x)){std::fprintf(stderr,"FAIL %d: %s\\n",__LINE__,#x);return 1;}}while(0)\nstruct Fixture {\n IR::Block entry,header,latch,exit;Gcn::Block cfg,head_cfg,exit_cfg;\n std::vector<std::unique_ptr<IR::Inst>> pool;\n IR::Inst *phi,*step,*cmp,*cond,*read,*root,*otherroot,*shift,*index;\n std::array<IR::Inst*,8> words;\n IR::Inst* add(O op,std::initializer_list<V> args={}){auto p=std::make_unique<IR::Inst>(op);p->args=args;p->parent=&header;auto* v=p.get();pool.push_back(std::move(p));return v;}\n Fixture(u32 seed=0,u32 bound=5){\n  head_cfg.ir_block=&header;exit_cfg.ir_block=&exit;cfg.branch_true=&head_cfg;cfg.branch_false=&exit_cfg;latch.cfg_block=&cfg;header.preds={&entry,&latch};\n  phi=add(O::Phi);step=add(O::IAdd32,{V(phi),V(1u)});step->parent=&latch;\n  phi->args={V(seed),V(step)};phi->phi_blocks={&entry,&latch};\n  cmp=add(O::SLessThan32,{V(phi),V(bound)});cond=add(O::ConditionRef,{V(cmp)});latch.branch_cond=V(cond);\n  auto* lo=add(O::GetUserData);auto* hi=add(O::GetUserData);root=add(O::CompositeConstructU32x2,{V(lo),V(hi)});otherroot=add(O::CompositeConstructU32x2,{V(lo),V(hi)});\n  shift=add(O::ShiftLeftLogical32,{V(phi),V(5u)});index=add(O::ShiftRightLogical32,{V(shift),V(2u)});\n  // Reproduce the two 16-byte halves of a raw 32-byte descriptor.\n  auto* upper=add(O::IAdd32,{V(shift),V(16u)});auto* upper_index=add(O::ShiftRightLogical32,{V(upper),V(2u)});\n  for(u32 i=0;i<8;++i){auto* b=i<4?index:upper_index;auto* offset=i%4?add(O::IAdd32,{V(b),V(i%4)}):b;words[i]=add(O::ReadConst,{V(i<4?root:otherroot),V(offset)});}\n  auto* low=add(O::CompositeConstructU32x4,{V(words[0]),V(words[1]),V(words[2]),V(words[3])});\n  auto* high=add(O::CompositeConstructU32x4,{V(words[4]),V(words[5]),V(words[6]),V(words[7])});\n  auto* handle=add(O::ImageHandle,{V(low),V(high)});read=add(O::ImageRead,{V(handle)});\n }\n};\nint main(){\n {Fixture f;auto p=Analyze(*f.read);CHECK(p);CHECK(p->range.first==0);CHECK(p->range.count==6);for(u32 s=0;s<6;++s)for(u32 w=0;w<8;++w)CHECK(p->offsets[s][w]==s*8+w);}\n for(u32 seed=0;seed<150;++seed)for(u32 distance=0;distance<22;++distance){\n  Fixture f(seed,seed+distance);for(auto op:{O::SLessThan32,O::ULessThan32}){\n   f.cmp->opcode=op;auto p=Analyze(*f.read);CHECK(bool(p)==(distance<16));\n   if(p){u32 real=seed;for(u32 iteration=0;;++iteration){CHECK(iteration<p->range.count);CHECK(real==p->range.first+iteration);for(u32 w=0;w<8;++w)CHECK(p->offsets[iteration][w]==real*8+w);if(!(real<seed+distance)){CHECK(iteration+1==p->range.count);break;}++real;}}\n  }\n }\n {Fixture f;f.step->args={V(1u),V(f.phi)};CHECK(Analyze(*f.read));}\n {Fixture f;std::swap(f.phi->args[0],f.phi->args[1]);std::swap(f.phi->phi_blocks[0],f.phi->phi_blocks[1]);CHECK(Analyze(*f.read));}\n {Fixture f;f.cfg.branch_true=&f.exit_cfg;f.cfg.branch_false=&f.head_cfg;CHECK(!Analyze(*f.read));}\n {Fixture f;f.cfg.branch_false=&f.head_cfg;CHECK(!Analyze(*f.read));}\n {Fixture f;f.latch.cfg_block=nullptr;CHECK(!Analyze(*f.read));}\n {Fixture f;f.header.preds.push_back(&f.exit);CHECK(!Analyze(*f.read));}\n {Fixture f;f.header.preds[1]=&f.exit;CHECK(!Analyze(*f.read));}\n {Fixture f;f.phi->phi_blocks[1]=&f.entry;CHECK(!Analyze(*f.read));}\n {Fixture f;f.step->parent=&f.entry;CHECK(!Analyze(*f.read));}\n {Fixture f;f.step->args[1]=V(2u);CHECK(!Analyze(*f.read));}\n {Fixture f;f.cmp->args[0]=V(f.step);CHECK(!Analyze(*f.read));}\n {Fixture f;f.cmp->args[1]=V(f.root);CHECK(!Analyze(*f.read));}\n {Fixture f;f.phi->args[0]=V(0xffffffffu);CHECK(!Analyze(*f.read));}\n {Fixture f;f.cmp->args[1]=V(0x80000000u);CHECK(!Analyze(*f.read));}\n {Fixture f;f.phi->args[1]=V(1u);CHECK(!Analyze(*f.read));}\n {Fixture f;f.words[3]->opcode=O::ReadConstBuffer;CHECK(!Analyze(*f.read));}\n {Fixture f;f.words[3]->args[1]=V(f.shift);CHECK(!Analyze(*f.read));}\n {Fixture f;f.root->args[0]=V(f.add(O::ReadLane));CHECK(!Analyze(*f.read));}\n {Fixture f;f.otherroot->args[0]=V(f.add(O::GetUserData));CHECK(!Analyze(*f.read));}\n {Fixture f;f.words[7]->args[1]=V(f.add(O::Phi));CHECK(!Analyze(*f.read));}\n {Fixture f;f.shift->args[1]=V(32u);CHECK(!Analyze(*f.read));}\n {Fixture f;f.read->info.is_array=true;CHECK(!Analyze(*f.read));f.read->info.is_array=false;f.read->info.has_lod=true;CHECK(!Analyze(*f.read));}\n // Offset arithmetic uses actual 32-bit wrap, with >31 shifts refused.\n {Fixture f;u32 rng=1;for(unsigned i=0;i<100000;++i){rng=rng*1664525u+1013904223u;u32 a=rng;rng=rng*1664525u+1013904223u;u32 b=rng;for(auto op:{O::IAdd32,O::ISub32,O::IMul32,O::BitwiseAnd32}){\n   auto* e=f.add(op,{V(a),V(b)});auto got=Offset(V(e),f.phi,0);u32 want=op==O::IAdd32?a+b:op==O::ISub32?a-b:op==O::IMul32?u32(u64(a)*b):a&b;CHECK(got&&*got==want);\n  }}}\n std::printf("FINITE_RAW_IMAGE_PLAN=PASS checks=%u\\n",checks);\n}\n'
PRE='\n#include <array>\n#include <vector>\n#include <cstdio>\n#include <cstdlib>\nusing u32=unsigned;using Id=unsigned;\nnamespace IR{struct Inst{};}\nnamespace spv {enum class SelectionControlMask{MaskNone};}\nstruct EmitContext {\n std::array<Id,5> F32{0,1,2,3,4};Id last_label=10;Id next=100;\n Id then_label=0,else_label=0,chosen=0,merge=0;unsigned reads=0;unsigned passed_handle=0;Id passed_coords=0,passed_lod=0,passed_ms=0;bool bad=false;std::vector<Id> labels;\n Id OpLabel(){return next++;}\n void OpSelectionMerge(Id m,spv::SelectionControlMask){merge=m;}\n void OpBranchConditional(Id condition,Id t,Id f){then_label=t;else_label=f;chosen=condition?t:f;}\n void AddLabel(Id label){last_label=label;labels.push_back(label);}\n void OpBranch(Id label){if(label!=merge)bad=true;}\n template<class...A>Id ConstF32(A... x){if(last_label!=else_label||sizeof...(x)!=4||((x!=0.0f)||...))bad=true;return 0;}\n Id OpPhi(Id type,Id yes,Id yes_block,Id no,Id no_block){if(type!=4||last_label!=merge||yes_block!=then_label||no_block!=else_label)bad=true;return chosen==then_label?yes:no;}\n};\nId EmitImageRead(EmitContext& ctx,IR::Inst*,u32 h,Id c,Id l,Id m){\n if(ctx.last_label!=ctx.then_label)ctx.bad=true;\n if(ctx.chosen==ctx.then_label){++ctx.reads;ctx.passed_handle=h;ctx.passed_coords=c;ctx.passed_lod=l;ctx.passed_ms=m;}return 123;\n}\n'
POST='\nint main(){unsigned checks=0;for(unsigned h=0;h<64;++h){for(unsigned c=0;c<8;++c){for(unsigned l=0;l<4;++l){for(unsigned m=0;m<4;++m){for(unsigned cond=0;cond<2;++cond){\n EmitContext ctx;auto result=EmitImageReadGuarded(ctx,nullptr,h,c,l,m,cond);++checks;\n if(ctx.bad||ctx.reads!=cond||result!=(cond?123:0)||ctx.labels.size()!=3)return 1;\n if(cond&&(ctx.passed_handle!=h||ctx.passed_coords!=c||ctx.passed_lod!=l||ctx.passed_ms!=m))return 2;\n}}}}}\nstd::printf("GUARDED_IMAGE_EMISSION_CONTRACT=PASS cases=%u\\n",checks);}\n'
def run(root,evid):
    work=evid/"contract-fixtures";work.mkdir(parents=True,exist_ok=True)
    (work/"ir_contract.h").write_text(STUB)
    for name in ("shader_recompiler/frontend/control_flow_graph.h","shader_recompiler/ir/basic_block.h"):
        p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text('#include "ir_contract.h"\n')
    (work/"plan.cpp").write_text(TEST)
    image=(root/"src/shader_recompiler/backend/spirv/emit_spirv_image.cpp").read_text()
    start=image.index("Id EmitImageReadGuarded(");end=image.index("\nvoid EmitImageWrite(",start)
    (work/"emit.cpp").write_text(PRE+image[start:end]+POST)
    tested=[]
    for cxx in ("g++","clang++"):
        if not shutil.which(cxx):continue
        for name in ("plan","emit"):
            binary=work/(name+"-"+cxx.replace("+","p"))
            args=[cxx,"-std=c++20","-O2","-Wall","-Wextra","-Werror","-pedantic","-I"+str(work),"-I"+str(root/"src"),str(work/(name+".cpp")),"-o",str(binary)]
            with (evid/(name+"-"+cxx.replace("+","p")+".log")).open("wb") as log:
                subprocess.run(args,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=120)
                subprocess.run([str(binary)],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=40)
            binary.unlink()
        tested.append(cxx)
    if not tested:raise RuntimeError("NO_CPP20_COMPILER")
    return tested
if __name__=="__main__":print(run(Path(sys.argv[1]),Path(sys.argv[2])))
